#!/usr/bin/env node
/**
 * Import the gym objects from the Nucleo icon library into the graphics module.
 *
 *   node scripts/import-nucleo-objects.mjs            (from marketing-site/)
 *
 * Source: the Nucleo Pro "core" family, glyph style, 48 px, from the local Nucleo Skills install
 * (`npx @nucleoicons/skills setup`). Set NUCLEO_SKILLS_ROOT to use another install folder.
 * Output: components/brand/graphics/nucleo-art.ts (generated; do not edit by hand).
 *
 * Nucleo marks the secondary parts of a glyph with data-color="color-2". They become paint "b"
 * (the detail tone); every other part becomes paint "a" (the body tone). See scheme.ts.
 * The icons are licensed to the project owner's Nucleo account. Ship them inside the products only;
 * do not publish the source set.
 */
import { readFileSync, writeFileSync } from "node:fs"
import { homedir } from "node:os"
import { dirname, join, resolve } from "node:path"
import { fileURLToPath } from "node:url"

/** Object id in the graphics module → Nucleo core label. Order sets the specimen order. */
export const OBJECTS = {
  plate: "weight-plate",
  dumbbell: "dumbbell",
  barbell: "barbell",
  kettlebell: "kettlebell",
  "squat-rack": "squat-rack",
  bench: "incline-bench",
  "medicine-ball": "medicine-ball",
  "punching-bag": "punching-bag",
  "resistance-band": "resistance-band",
  "spin-bike": "spinning-bike",
  rower: "rowing-machine",
  treadmill: "treadmill",
  "jump-rope": "skipping-rope",
  stopwatch: "stopwatch",
  sneaker: "sneaker",
  cone: "traffic-cone",
  pool: "swimming-pool",
  wave: "water-wave",
  paddle: "table-tennis",
  "tennis-ball": "tennis-ball",
  basketball: "basketball",
  mat: "mat",
  "spa-stones": "spa-stones",
  towel: "towel",
  "water-bottle": "water-bottle",
  shaker: "protein-shaker",
  whistle: "whistle",
  "gym-bag": "gym-bag",
  playground: "playground",
  key: "key",
  schedule: "workout-schedule",
  "heart-watch": "watch-heartbeat",
  sun: "sun",
}

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..")
const nucleo =
  process.env.NUCLEO_SKILLS_ROOT ?? join(homedir(), ".nucleo", "skills")

function main() {
  const index = JSON.parse(
    readFileSync(join(nucleo, "core", "icons.json"), "utf8")
  )
  const byLabel = new Map()
  for (const icon of index.icons)
    if (
      icon.fills.length === 1 &&
      icon.fills[0] === "glyph" &&
      icon.sizes.length === 1 &&
      icon.sizes[0] === "48px" &&
      !byLabel.has(icon.label)
    )
      byLabel.set(icon.label, icon)

  const lines = []
  for (const [id, label] of Object.entries(OBJECTS)) {
    const icon = byLabel.get(label)
    if (!icon) throw new Error(`Nucleo core 48px glyph "${label}" not found`)
    const els = []
    for (const [, attrs] of icon.svg.matchAll(/<path([^>]*)>/g)) {
      const d = attrs.match(/\sd="([^"]+)"/)?.[1]
      if (!d) continue
      const fill = /data-color="color-2"/.test(attrs) ? "b" : "a"
      const rule = /fill-rule="evenodd"/.test(attrs) ? ', rule: "evenodd"' : ""
      els.push(`{ k: "path", d: "${d}", fill: "${fill}"${rule} }`)
    }
    lines.push(
      `  /** Nucleo core "${label}" (#${icon.id}), glyph, 48 px. */\n  "${id}": [{ k: "g", x: 4, y: 4, s: 92 / 48, ch: [\n    ${els.join(",\n    ")},\n  ] }],`
    )
  }

  const out = `// Generated by scripts/import-nucleo-objects.mjs from the Nucleo core family. Do not edit by hand.
import type { El, ObjPaint } from "./types"

/** Each object on the 100-unit square: the 48 px glyph scaled to 92 units, with a 4-unit margin. */
export const nucleoArt = {
${lines.join("\n")}
} as const satisfies Record<string, El<ObjPaint>[]>
`
  const file = join(root, "components/brand/graphics/nucleo-art.ts")
  writeFileSync(file, out)
  console.log(
    `Wrote ${Object.keys(OBJECTS).length} objects to ${file} from ${nucleo}`
  )
}

if (import.meta.main) main()
